memo: dict = {}

def value(remaining_hits: int, state: tuple) -> Q:
    if remaining_hits == 0:
        return Q(0)
    key = (remaining_hits, state)
    if key in memo:
        return memo[key]
    chosen = max(state, key=lambda pair: (Q(pair[1], pair[0]), -pair[0]))
    size, failures = chosen
    rest = list(state)
    rest.remove(chosen)
    hit = Q(failures, size)
    after_hit = tuple(sorted(rest + ([(size - 1, failures - 1)] if failures > 1 else [])))
    result = 1 + hit * value(remaining_hits - 1, after_hit)
    if hit < 1:
        after_miss = tuple(sorted(rest + [(size - 1, failures)]))
        result += (1 - hit) * value(remaining_hits, after_miss)
    memo[key] = result
    return result

return value(hits_needed, tuple(sorted(pair for pair in counts if pair[1] > 0)))

